/* Kielo Learning Centre — clickable design mockup */
(() => {
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const nav = [
    { group: 'Start here', items: [['home','⌂','Learning home'],['path','↗','Learning path'],['placement','◎','Find my level']] },
    { group: 'Words & review', items: [['daily','◷','Daily 100','100'],['dictionary','⌕','Dictionary'],['practice','✳','Practice & review']] },
    { group: 'Skill labs', items: [['sounds','♫','Pronunciation'],['listening','◖','Listening'],['spoken','〝','Spoken Finnish'],['speaking','◉','Speaking'],['reading','▤','Reading'],['writing','✎','Writing'],['grammar','⌘','Grammar lab'],['cafe','☕','Conversation'],['voice','♬','Voice studio'],['videos','▷','Video lessons']] },
    { group: 'Life in Finland', items: [['culture','⌖','Finland explorer']] }
  ];
  const titles = Object.fromEntries(nav.flatMap(g => g.items.map(([id,icon,title]) => [id,title])));
  const words = [
    ['leipä','bread','রুটি','🍞','noun'],['pyörä','bicycle','সাইকেল','🚲','noun'],['jääkaappi','refrigerator','ফ্রিজ','🧊','noun'],['kymmenen','ten','দশ','🔟','number'],['mehu','juice','জুস','🧃','noun'],['kahvila','café','ক্যাফে','☕','place'],['apu','help','সাহায্য','🤝','noun'],['harrastaa','to have a hobby','শখ করা','🎨','verb'],['koira','dog','কুকুর','🐕','noun'],['helppo','easy','সহজ','🌱','adjective']
  ];
  const fullVocabulary = () => [...words,...(window.KIELO_DAILY_WORDS||[]).map(w=>[w.fi,w.en,w.bn,'🔤',w.level||'A1'])];
  const topics = [
    ['⌛','History & independence','From ancient roots to modern Finland','Get your bearings'],['🏛','Government & public services','How Finland is organised and where to get help','Get your bearings'],['👥','People, languages & society','The people and languages of Finland','Get your bearings'],['❄','Climate & seasons','Light, snow, summer and everyday weather','Get your bearings'],['🌲','Forests & nature','Everyman’s rights and life in the forest','Explore the land'],['🌊','Lakes, sea & archipelago','Waterways, coastlines and island life','Explore the land'],['🚋','Traffic & transport','Tickets, buses, trains and cycling','Move through daily life'],['🎓','Universities & study','Degrees, student life and applications','Make a life'],['💼','Jobs & working life','Finding work and understanding work life','Make a life'],['🥕','Farming, markets & food','Seasonal food, markets and Finnish meals','Move through daily life'],['📍','Cities, regions & places','Meet Finland from Helsinki to Lapland','Explore the land'],['🎨','Culture, design & media','Design, music, books and public media','Move through daily life'],['🏠','Housing & home life','Homes, rent, saunas and everyday routines','Make a life'],['♡','Health & wellbeing','Healthcare, wellbeing and how services work','Make a life'],['🎄','Holidays & yearly traditions','The Finnish calendar through the year','Move through daily life'],['€','Money, banking & taxes','Practical money words and services','Make a life'],['⚡','Energy & electricity','How energy shapes homes and society','Explore the land'],['⚽','Sports & movement','Popular sports and active everyday life','Move through daily life'],['🧳','Moving to Finland & registration','First steps, registration and settling in','Make a life']
  ];
  const levels = [['Pre-A1','First words','Meet sounds, greetings and simple needs','6 lessons'],['A1','Everyday basics','Talk about yourself, home and routines','9 lessons'],['A2','Growing confidence','Handle familiar tasks and short stories','9 lessons'],['B1','Independent Finnish','Share experiences and follow key ideas','9 lessons'],['B2','Fluent expression','Discuss complex topics with confidence','9 lessons'],['C1','Advanced Finnish','Understand nuance in study and work','9 lessons'],['C2','Mastery','Use Finnish flexibly and precisely','9 lessons']];
  let screen = location.hash.slice(1) || 'home';
  let dailySet = 1, dailyFilter = 'All words', topicIndex = 0, quizChoice = -1, lessonStep = 0;
  const bn = () => $('#help-language').value === 'bn';
  const translation = (en,bengali) => `<span class="meaning">${bn() ? bengali : en}</span>`;
  const btn = (label, action, style='secondary', extra='') => `<button class="button button-${style}" type="button" data-action="${action}" ${extra}>${label}</button>`;
  const pageHead = (kicker,title,desc,actions='') => `<header class="page-heading"><div class="page-heading-copy"><span class="page-kicker">${kicker}</span><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></header>`;
  const section = (eyebrow,title,desc,body,action='') => `<section class="section"><div class="section-head"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${action}</div>${body}</section>`;
  const card = (body, extra='') => `<article class="card ${extra}">${body}</article>`;
  const scene = (label,title,emoji='🌲') => `<div class="scene-card" style="background:linear-gradient(90deg,rgba(17,54,45,.77),rgba(17,54,45,.12)),url('../public/images/kielo-cover.webp') center/cover"><div class="scene-meta">${label}</div><h3>${title}</h3><span class="scene-emoji">${emoji}</span></div>`;
  const wordCards = (list=words) => `<div class="word-grid">${list.map(([fi,en,bg,emoji,type])=>`<article class="word-card"><div class="word-card-top"><span class="word-icon">${emoji}</span><span class="tag">${type}</span><button class="play" data-speak="${fi}" aria-label="Play ${fi}">▶</button></div><h3>${fi}</h3><p>${translation(en,bg)}</p><div class="word-card-actions"><span class="muted">${type==='verb'?'verb · verb type 1':/^(Pre-A1|A1|A2|B1|B2|C1|C2|Finland)/.test(type)?'Learning level · '+type:'Finnish · singular'}</span><button data-action="save-word" data-word="${fi}">＋ Save</button></div></article>`).join('')}</div>`;
  const levelCards = () => `<div class="level-grid">${levels.map(([level,name,desc,count],i)=>`<button class="level-card ${i===0?'active':''}" data-action="open-lesson" data-level="${level}"><span class="level-card-top"><span class="level-pill">${level}</span><span>${i<2?'●':'○'}</span></span><h3>${name}</h3><p>${desc}</p><span class="level-card-foot"><span>${count} lessons</span><span>Open path →</span></span></button>`).join('')}</div>`;
  function home(){return `${pageHead('LEARN FINNISH · START HERE','A little Finnish, every day.','A guided course from your very first Finnish sounds to advanced fluency—with useful words and a closer look at life in Finland.',btn('Find my level','placement','secondary')+btn('Continue learning','lesson','primary'))}<div class="home-hero"><article class="welcome-card"><span class="card-label">YOUR NEXT SMALL STEP · PRE-A1</span><h2>Start with a hello.</h2><p>Learn your first friendly Finnish greeting and say it out loud.</p><div class="welcome-actions">${btn('Start first lesson','lesson','primary')}${btn('Explore the course','path','secondary')}</div><span class="welcome-note">⏱ About 5 minutes · English or বাংলা explanations</span></article><article class="continue-card"><div class="continue-art" style="background-image:linear-gradient(0deg,rgba(16,55,46,.72),transparent 65%),url('../public/images/kielo-cover.webp')"></div><div class="continue-content"><span class="eyebrow">TODAY IN FINLAND · USEFUL FINNISH</span><h3>Hei! Harjoitellaan suomea yhdessä.</h3><p>Hi! Let’s practise Finnish together.</p></div><div class="continue-meta"><span>LESSON 1 OF 60 · PRE-A1</span><button data-speak="Hei! Harjoitellaan suomea yhdessä." class="play">▶ Listen</button></div></article></div>${section('YOUR DAILY RHYTHM','One short session goes a long way','Pick up where you like; your learning pace stays yours.',`<div class="stat-grid"><div class="stat-card"><span class="stat-icon">◷</span><div class="stat-copy"><small>TODAY’S WORDS</small><strong>0 <small>/ 10</small></strong></div></div><div class="stat-card"><span class="stat-icon">✳</span><div class="stat-copy"><small>READY TO REVIEW</small><strong>12 <small>words</small></strong></div></div><div class="stat-card"><span class="stat-icon">↗</span><div class="stat-copy"><small>COURSE PROGRESS</small><strong>06 <small>/ 60 lessons</small></strong></div></div><div class="stat-card"><span class="stat-icon">☀</span><div class="stat-copy"><small>YOUR STREAK</small><strong>3 <small>days</small></strong></div></div></div>`)}${section('CHOOSE A WAY IN','What would you like to practise?','Every tool below connects back to your Finnish course.',`<div class="home-quick-grid">${[['◷','Daily 100','Ten-minute words','daily'],['⌕','Dictionary','Find a Finnish word','dictionary'],['♫','Sound lab','Hear each Finnish sound','sounds'],['☕','Conversation','Practise a real situation','cafe']].map(([i,n,d,a])=>`<button class="quick-card" data-screen="${a}"><span class="tool-icon">${i}</span><span class="quick-card-copy"><strong>${n}</strong><small>${d}</small></span><span>→</span></button>`).join('')}</div>`)}${section('YOUR COURSE · PRE-A1 TO C2','A clear path from first words to fluency','Seven CEFR levels · 60 guided lessons · small steps and real-life practice',levelCards(),`<button class="text-link" data-screen="path">View full path →</button>`)}${section('FINNISH THROUGH FINLAND','Language makes everyday life feel closer','Explore useful Finnish in the context of Finland’s people, places, services and seasons.',`<div class="home-quick-grid">${[['🌲','Forest & nature','Language for a walk in the woods','culture'],['🎓','Study & universities','Study-life Finnish','culture'],['🚋','Getting around','Buses, tickets and directions','culture'],['💼','Work life','Words for work and job search','culture']].map(([i,n,d,a])=>`<button class="quick-card" data-screen="${a}"><span class="tool-icon">${i}</span><span class="quick-card-copy"><strong>${n}</strong><small>${d}</small></span><span>→</span></button>`).join('')}</div>`)}${section('A KIND WAY TO BEGIN','You do not need to know anything yet.','Start with sounds, then add words, phrases and confidence. Explanations can be switched between English and বাংলা at any time.',`<div class="goal-card"><div><span class="eyebrow">YOUR DAILY GOAL</span><h3>How many new words feel right today?</h3><p>Change your goal whenever you like; progress is saved on this device in this mockup.</p></div><div class="goal-control"><select aria-label="Daily goal"><option>10 words</option><option>20 words</option><option>50 words</option><option>100 words</option></select>${btn('Save goal','toast','soft','data-message="Daily goal saved for this preview."')}</div></div>`)}`}
  function path(){return `${pageHead('YOUR COURSE · 7 LEVELS · 60 LESSONS','Your Finnish, step by step.','Move from your first hello to confident Finnish for study, work and everyday life. Every level builds the four skills: listening, speaking, reading and writing.',btn('Take a 3-minute level check','placement','primary'))}${section('THE LEARNING PATH','Choose a level','Start at the beginning, or take the level check if you already know some Finnish.',levelCards())}${section('YOUR NEXT LESSON','Meet someone in Finland','Lesson 1 · Greetings and introductions · Pre-A1 · about 5 minutes',`<div class="lesson-list">${[['01','Say hello','Hei! · Moi!','5 min','Start'],['02','Your name','Minä olen…','6 min','Next'],['03','Where are you from?','Olen Bangladeshista.','7 min','Next'],['04','A first conversation','Hei, mitä kuuluu?','8 min','Next']].map(([n,t,ex,time,state],i)=>`<button class="lesson-row" data-action="lesson-step" data-step="${i}"><span class="lesson-row-number">${n}</span><span><strong>${t}</strong><small>${ex}</small></span><span class="muted">${time}</span><span class="tag">${state}</span></button>`).join('')}</div>`)}${section('COURSE DESIGN','Learn a little in four ways','Each guided lesson moves through a tiny, practical sequence.',`<div class="home-quick-grid">${[['01 · Notice','See a real situation','A picture, a short story or a useful phrase'],['02 · Listen','Hear natural Finnish','Replay at a pace that feels comfortable'],['03 · Try','Use the language','Choose, match, speak or write'],['04 · Remember','Bring it back later','Quick review helps new Finnish stay with you']].map(([a,b,c])=>`<article class="quick-card"><span class="tool-icon">${a.slice(0,2)}</span><span class="quick-card-copy"><strong>${b}</strong><small>${c}</small></span></article>`).join('')}</div>`)}`}
  function daily(){const source=Array.isArray(window.KIELO_DAILY_WORDS)?window.KIELO_DAILY_WORDS:[];const start=(dailySet-1)*10;let batch=source.slice(start,start+10).map(word=>[word.fi,word.en,word.bn,'🔤',word.level||'A1']);if(batch.length<10)batch=[...batch,...words.slice(0,10-batch.length)];const filtered=dailyFilter==='Beginner'?batch.filter(w=>['Pre-A1','A1'].includes(w[4])):dailyFilter==='Everyday'?batch.filter(w=>['A2','B1'].includes(w[4])):dailyFilter==='Advanced'?batch.filter(w=>['B2','C1','C2'].includes(w[4])):batch;return `${pageHead('WORDS · A FRESH SET EVERY DAY','100 useful Finnish words.','A rotating daily collection grouped into ten small sets. Study 10, 20, 50 or all 100—with Finnish audio, examples and review.',`<label class="filter-chip">TODAY’S TARGET <select><option>10 words</option><option>20 words</option><option>50 words</option><option>100 words</option></select></label>`)}<div class="goal-card"><div><span class="eyebrow">TODAY’S LEARNING PLAN</span><h3>Ten words at a time</h3><p>100 words · 10 sets · repeat a sound, see an example and save the words you want to remember.</p></div><div class="goal-control"><span class="tag">SET ${dailySet} OF 10</span>${btn('Quick word quiz','practice','primary')}</div></div>${section('SET '+dailySet+' · WORDS '+(start+1)+'–'+Math.min(start+10,100),'A few useful words for today','Change the set to browse 100 different words from the existing Finnish learning collection.',`<div class="daily-sets">${Array.from({length:10},(_,i)=>`<button class="set-chip ${dailySet===i+1?'active':''}" data-set="${i+1}">Set ${i+1}<small>${String(i*10+1).padStart(2,'0')}–${String((i+1)*10).padStart(2,'0')}</small></button>`).join('')}</div><div class="tab-row">${['All words','Beginner','Everyday','Advanced'].map(x=>`<button class="tab-button ${dailyFilter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div>${wordCards(filtered.length?filtered:batch)}`)}${section('HOW YOUR DAILY 100 WORKS','Small enough to finish, useful enough to keep','Today’s collection changes by date; saved and difficult words return in your review.',`<div class="home-quick-grid"><article class="quick-card"><span class="tool-icon">01</span><span class="quick-card-copy"><strong>Learn in tens</strong><small>A short session can be just ten words.</small></span></article><article class="quick-card"><span class="tool-icon">02</span><span class="quick-card-copy"><strong>Hear Finnish</strong><small>Tap a speaker to hear the word.</small></span></article><article class="quick-card"><span class="tool-icon">03</span><span class="quick-card-copy"><strong>Remember it</strong><small>Save words and revisit them later.</small></span></article><article class="quick-card"><span class="tool-icon">04</span><span class="quick-card-copy"><strong>Use it in a phrase</strong><small>Learn words in everyday context.</small></span></article></div>`)}`}
  function dictionary(){return `${pageHead('WORD FINDER · FINNISH WITH CONTEXT','A Finnish dictionary that teaches.','Search Finnish, English or বাংলা. See a clear meaning, hear the word and notice how it changes in a sentence.',btn('Explore word forms','morphology','secondary'))}<form class="dictionary-search" id="dictionary-form"><span>⌕</span><input id="dictionary-input" placeholder="Try leipä, bread, or রুটি" aria-label="Search Finnish dictionary"><select aria-label="Dictionary category"><option>All word types</option><option>Nouns</option><option>Verbs</option><option>Adjectives</option></select><button class="button button-primary">Search</button></form><div id="dictionary-results">${section('TODAY’S SUGGESTIONS','A few good words to know','Every entry is built for learners, with translations and simple examples.',wordCards(words.slice(0,6)))}</div>${section('LEARN HOW A WORD CHANGES','A small grammar guide, right beside your word','Open a word form to explore its most useful Finnish patterns.',`<div class="case-grid">${[['talo','house · a home'],['talossa','in the house'],['talosta','from the house'],['taloon','into the house']].map(([f,m])=>`<button class="case-card" data-action="morphology"><strong>${f}</strong><span>${m}</span></button>`).join('')}</div>`)}`}
  function practice(){return `${pageHead('PRACTICE · REMEMBER WHAT YOU KNOW','A friendly little review.','Review saved words, revisit tricky sounds and practise one quick question at a time.',btn('Change activity','daily','secondary'))}${section('YOUR REVIEW QUEUE','12 words are ready to revisit','Words you save or find difficult can come back here.',`<article class="review-card"><div class="review-picture">🍞</div><div class="review-copy"><span class="eyebrow">FINNISH · NOUN</span><h3>leipä</h3><p>Can you remember what this word means?</p><div class="rating-row">${['Bread','Cheese','Milk'].map((x,i)=>`<button class="${quizChoice===i?(i===0?'correct':'incorrect'):''}" data-quiz="${i}">${x}</button>`).join('')}</div><div class="inline-status">${quizChoice<0?'Choose one answer to continue.':quizChoice===0?'Correct — leipä means bread.':'Try once more: tap the speaker, then choose again.'}</div></div></article>`)}${section('PICK A PRACTICE STYLE','Keep it light and active','Try a quick activity or choose a skill to strengthen.',`<div class="home-quick-grid">${[['⌕','Word match','Match Finnish and meaning','match'],['♫','Listen & choose','Hear the word, pick the answer','listen-quiz'],['✎','Build a sentence','Put useful words in order','writing'],['◉','Speak a phrase','Practise at your own pace','speaking']].map(([i,n,d,a])=>`<button class="quick-card" data-screen="${a==='match'||a==='listen-quiz'?'practice':a}"><span class="tool-icon">${i}</span><span class="quick-card-copy"><strong>${n}</strong><small>${d}</small></span><span>→</span></button>`).join('')}</div>`)}`}
  function sounds(){const vowels=[['a','talo','house'],['o','koti','home'],['u','kuu','moon'],['e','vesi','water'],['i','kiitos','thank you'],['y','yksi','one'],['ä','käsi','hand'],['ö','yö','night']];return `${pageHead('SKILL LAB · HEAR THE FINNISH SOUNDS','Finnish sounds, one by one.','Listen for clear vowels and long sounds. Finnish spelling is consistent: each written letter has a sound.',btn('Hear a sound','speak-sample','soft','data-sample="yö"'))}${section('VOWEL SOUNDS','Meet the Finnish vowels','Tap a word to hear it. Notice how ä and ö are full letters, not decoration.',`<div class="word-grid">${vowels.map(([v,w,m])=>`<article class="word-card"><div class="word-card-top"><span class="tool-icon">${v}</span><span class="card-label">${'aeiouyäö'.includes(v)?'VOWEL':''}</span><button class="play" data-speak="${w}">▶</button></div><h3>${w}</h3><p>${translation(m,({house:'বাড়ি',home:'ঘর',moon:'চাঁদ',water:'পানি','thank you':'ধন্যবাদ',one:'এক',hand:'হাত',night:'রাত'})[m])}</p><small class="muted">${v==='ä'||v==='ö'?'Front vowel':'Clear, short vowel'}</small></article>`).join('')}</div>`)}${section('LONG AND SHORT SOUNDS','A tiny difference can change the word','Finnish keeps long sounds clear. Hold a long vowel or consonant for a little longer.',`<div class="compare-grid">${[['tuli','fire','tuuli','wind'],['muta','mud','muuta','other / change'],['kuka','who','kukka','flower']].map(([a,am,b,bm])=>`<div class="compare-card"><button data-speak="${a}"><strong>${a}</strong><span>${am}</span> ▶</button><span class="compare-arrow">↔</span><button data-speak="${b}"><strong>${b}</strong><span>${bm}</span> ▶</button></div>`).join('')}</div>`)}`}
  function listening(){return `${pageHead('SKILL LAB · LISTEN AT YOUR PACE','Listening gets easier with practice.','Start with one familiar situation. Listen once, then reveal the transcript and notice the words you already know.',btn('Hear the dialogue','speak-sample','primary','data-sample="Hei! Yksi kahvi, kiitos."'))}<div class="lesson-stage"><div class="lesson-stage-main">${scene('AT A HELSINKI CAFÉ · A1','Order a coffee','☕')}<article class="lesson-content-card"><span class="eyebrow">LISTEN FIRST · DON’T WORRY ABOUT EVERY WORD</span><h2>At the café counter</h2><p>Hear a small everyday exchange. You can slow it down or reveal the transcript when you are ready.</p><div class="scene-controls">${btn('▶ Play dialogue','speak-sample','primary','data-sample="Hei! Yksi kahvi, kiitos. Haluatko maitoa? Kyllä, kiitos."')}<label>Speed <select><option>Steady</option><option>Slow</option><option>Natural</option></select></label><button class="button button-secondary" data-action="transcript">Show transcript</button></div><div id="transcript-slot"></div></article></div><aside class="lesson-side"><article class="lesson-side-card"><span class="eyebrow">LISTEN FOR</span><h3>Yksi kahvi</h3><p>One coffee</p><button class="play" data-speak="Yksi kahvi">▶</button></article><article class="lesson-side-card"><span class="eyebrow">YOUR SKILL</span><strong>Listening · A1</strong><p>Short, everyday conversations</p></article></aside></div>${section('MORE LISTENING PATHS','Choose a scene that feels useful','Every scene brings a short dialogue, key phrases and one small check.',`<div class="home-quick-grid">${[['🚋','Buy a travel ticket','Tickets, times and destinations'],['🏪','At the supermarket','Find everyday items'],['🏠','Meet a neighbour','Simple greetings at home'],['🎓','On campus','Ask where a room is']].map(([i,n,d])=>`<button class="quick-card" data-action="change-scene"><span class="tool-icon">${i}</span><span class="quick-card-copy"><strong>${n}</strong><small>${d}</small></span><span>→</span></button>`).join('')}</div>`)}`}
  function spoken(){return `${pageHead('SKILL LAB · EVERYDAY FINNISH','Standard Finnish & spoken Finnish.','In everyday conversation, many Finns use relaxed forms. Learn the standard form first, then recognise the spoken version.',btn('Listen to both','speak-sample','secondary','data-sample="Minä olen. Mä oon."'))}${section('COMMON EVERYDAY FORMS','Spot the change','Spoken forms vary by person and place. These are common examples—not a rule to use in every situation.',`<div class="compare-grid">${[['minä','I','mä','spoken: I'],['sinä','you','sä','spoken: you'],['olen','am','oon','spoken: am'],['minulla on','I have','mul on','spoken: I have'],['mitä','what','mitä / mite','what (relaxed)'],['ei ole','is not / do not have','ei oo','spoken: is not']].map(([a,am,b,bm])=>`<div class="compare-card"><button data-speak="${a}"><span>STANDARD</span><strong>${a}</strong><small>${am}</small></button><span class="compare-arrow">↔</span><button data-speak="${b}"><span>SPOKEN</span><strong>${b}</strong><small>${bm}</small></button></div>`).join('')}</div>`)}${section('WHEN TO USE WHICH','Choose the form for your situation','Standard Finnish is a reliable choice in writing, formal settings and when you are learning.',`<div class="home-quick-grid"><article class="quick-card"><span class="tool-icon">✉</span><span class="quick-card-copy"><strong>Standard form</strong><small>Writing, study, work and clear communication.</small></span></article><article class="quick-card"><span class="tool-icon">☕</span><span class="quick-card-copy"><strong>Spoken form</strong><small>Recognise casual conversation with friends.</small></span></article></div>`)}`}
  function speaking(){return `${pageHead('SKILL LAB · SPEAK AT YOUR OWN PACE','Find your Finnish voice.','Practise a phrase, listen to a model and try it aloud. A microphone activity only starts when you choose to start it.',btn('Open voice studio','voice','secondary'))}<div class="lesson-stage"><div class="lesson-stage-main">${scene('SPEAKING PRACTICE · PRE-A1','Introduce yourself','👋')}<article class="lesson-content-card"><span class="eyebrow">TODAY’S SPEAKING PROMPT</span><h2>Say your name in Finnish.</h2><p>Start with a useful, flexible phrase. Listen first, then try at your own pace.</p><div class="topic-phrase"><strong>Minä olen Leoni.</strong><span>I am Leoni. · আমি লিওনি।</span><button class="play" data-speak="Minä olen Leoni.">▶ Listen</button></div><div class="response-area"><label for="practice-answer">Or write your answer first</label><input id="practice-answer" placeholder="Minä olen…"><div class="scene-controls"><button class="button button-primary" data-action="mic">◉ Start speaking practice</button><button class="button button-secondary" data-action="answer-check">Check my sentence</button></div><p class="muted">Speaking recognition is optional. You can always practise by listening and repeating.</p></div></article></div><aside class="lesson-side"><article class="lesson-side-card"><span class="eyebrow">SPEAKING SUPPORT</span><h3>Take one breath.</h3><p>Listen once. Say just the Finnish phrase. There is no timer.</p></article><article class="lesson-side-card"><span class="eyebrow">NEXT PRACTICE</span><strong>Where are you from?</strong><button class="text-link" data-action="next-prompt">Try this prompt →</button></article></aside></div>${section('SPEAKING FROM PRE-A1 TO C2','Build confidence one situation at a time','Short guided prompts grow into presentations, interviews, meetings and nuanced conversation.',`<div class="level-grid">${levels.map(([l,n,d])=>`<button class="level-card" data-action="open-lesson" data-level="${l}"><span class="level-pill">${l}</span><h3>${n}</h3><p>${d}</p><span class="level-card-foot">Open speaking prompts →</span></button>`).join('')}</div>`)}`}
  function reading(){return `${pageHead('SKILL LAB · READ AT YOUR LEVEL','Read Finnish that feels possible.','Choose a short text at your level. Read first, listen if you want, then check what you understood.',btn('Listen to the text','speak-sample','secondary','data-sample="Tänään Helsingissä paistaa aurinko. Ihmiset kävelevät puistossa."'))}${section('A1 · A SHORT FINNISH TEXT','A sunny day in Helsinki','Read the Finnish first. Meanings are here to support you, not interrupt the story.',`<article class="lesson-content-card"><span class="eyebrow">SUOMI · EVERYDAY LIFE</span><h2>Tänään Helsingissä</h2><div class="transcript"><p><strong>Tänään Helsingissä paistaa aurinko.</strong><br>${translation('Today the sun is shining in Helsinki.','আজ হেলসিঙ্কিতে রোদ উঠেছে।')}</p><p><strong>Ihmiset kävelevät puistossa.</strong><br>${translation('People are walking in the park.','মানুষ পার্কে হাঁটছে।')}</p><p><strong>Minä juon kahvia ystävän kanssa.</strong><br>${translation('I am drinking coffee with a friend.','আমি এক বন্ধুর সঙ্গে কফি পান করছি।')}</p></div><div class="scene-controls"><button class="button button-secondary" data-speak="Tänään Helsingissä paistaa aurinko. Ihmiset kävelevät puistossa. Minä juon kahvia ystävän kanssa.">▶ Listen to Finnish</button><button class="button button-primary" data-action="reading-quiz">Check understanding</button></div><div class="inline-status" id="reading-feedback">What is the weather like in Helsinki today?</div><div class="response-options">${['It is sunny.','It is snowing.','It is raining.'].map((a,i)=>`<button class="match-option" data-reading-answer="${i}">${a}</button>`).join('')}</div></article>`)}${section('CHOOSE YOUR READING LEVEL','From short notices to advanced writing','A guided library can grow from simple everyday text to journalism, academic text and literature.',`<div class="level-grid">${levels.map(([l,n,d])=>`<button class="level-card" data-action="reading-level" data-level="${l}"><span class="level-pill">${l}</span><h3>${n}</h3><p>${d}</p><span class="level-card-foot">Browse texts →</span></button>`).join('')}</div>`)}${section('REAL FINNISH MEDIA','Short news and learning resources','Curated external sources can link out with a clear note about level and difficulty.',`<article class="quick-card"><span class="tool-icon">Yle</span><span class="quick-card-copy"><strong>Yle Selkouutiset</strong><small>Easy-to-understand Finnish news · external source in the final site</small></span><span>↗</span></article>`)}`}
  function writing(){return `${pageHead('SKILL LAB · WRITE A LITTLE FINNISH','Writing practice without pressure.','Build a useful sentence, write a short message or practise at your level. Finnish character keys are always close by.',btn('Open grammar lab','grammar','secondary'))}${section('TODAY’S WRITING PROMPT','Write a small introduction','Pre-A1 · Write two or three sentences about yourself. You can start with the pattern below.',`<article class="prompt-card"><span class="eyebrow">A FRIENDLY STARTER</span><p>Hei! Minä olen _____. Olen kotoisin _____. Asun _____.</p><small>Hi! I am _____. I am from _____. I live in _____.</small></article><div class="editor-toolbar"><span>YOUR DRAFT · SAVED ON THIS DEVICE IN THIS PREVIEW</span><button class="button button-small button-secondary" data-action="clear-draft">Clear</button></div><textarea id="writing-draft" class="writing-editor" rows="7" placeholder="Hei! Minä olen…" aria-label="Write your Finnish practice"></textarea><div class="finnish-keys">${['ä','ö','å','Ä','Ö','Å'].map(k=>`<button type="button" data-key="${k}">${k}</button>`).join('')}</div><div class="scene-controls">${btn('Show a gentle hint','writing-hint','soft')}${btn('Save practice','toast','primary','data-message="Your writing is saved in this mockup."')}</div><div class="inline-status" id="writing-feedback"></div>`)}${section('WRITING CAN GROW WITH YOU','From a first sentence to study and work','Prompts are levelled and practical: a text message, a form, a short story, an email or an essay.',`<div class="home-quick-grid">${[['Pre-A1','Introduce yourself'],['A1','Write a short message'],['A2','Describe your day'],['B1','Tell a short story'],['B2','Write a clear opinion'],['C1–C2','Communicate with nuance']].map(([l,d])=>`<article class="quick-card"><span class="tool-icon">✎</span><span class="quick-card-copy"><strong>${l}</strong><small>${d}</small></span></article>`).join('')}</div>`)}`}
  function grammar(){return `${pageHead('SKILL LAB · GRAMMAR IN SMALL PIECES','Finnish grammar, made visible.','Explore one useful pattern at a time, notice it in a real phrase and practise before moving on.',btn('Choose a grammar topic','grammar-topics','secondary'))}${section('START WITH A SENTENCE','Where is the house?','Finnish endings often show a place relationship. Tap each form to hear it.',`<div class="case-grid">${[['talo','house · talo'],['talossa','in the house · talossa'],['talosta','out of the house · talosta'],['taloon','into the house · taloon'],['talolla','at / by the house · talolla'],['talolle','to the house · talolle']].map(([f,m])=>`<button class="case-card" data-speak="${f}"><strong>${f}</strong><span>${m}</span></button>`).join('')}</div><article class="grammar-example"><span class="eyebrow">NOTICE THE ENDING</span><strong>Minä asun talossa.</strong><p>I live in a house. · <span class="bn">আমি একটি বাড়িতে থাকি।</span></p><button class="play" data-speak="Minä asun talossa.">▶ Listen</button></article>`)}${section('EXPLORE GRAMMAR','A map of useful patterns','Start with common everyday forms. Advanced patterns unlock as you progress.',`<div class="home-quick-grid">${[['Word forms','Cases and endings · talo → talossa'],['Verb patterns','Who does what · minä puhun'],['Questions','Ask what, where and when'],['Past & future','Talk about yesterday and plans'],['Negative forms','Say what is not or did not happen'],['Word order','Make a sentence clear and natural']].map(([t,d])=>`<button class="quick-card" data-action="grammar-topic"><span class="tool-icon">⌘</span><span class="quick-card-copy"><strong>${t}</strong><small>${d}</small></span><span>→</span></button>`).join('')}</div>`)}${section('TRY ONE','Choose the correct form','Minä asun ___ (in the house).',`<div class="response-options">${['talo','talossa','talosta'].map((x,i)=>`<button class="match-option ${quizChoice===i?(i===1?'correct':'incorrect'):''}" data-grammar-answer="${i}">${x}</button>`).join('')}</div><p class="inline-status">${quizChoice<0?'Pick the ending that means “in the house”.':quizChoice===1?'Correct — -ssa / -ssä often means “in”.':'Have another look at talossa: the ending signals “in”.'}</p>`)}`}
  function cafe(){return `${pageHead('SKILL LAB · ROLEPLAY EVERYDAY MOMENTS','Practise a real conversation.','Take a small role in a Finnish situation. Read, listen and reply by choosing or typing a phrase.',btn('Choose another scene','scene-list','secondary'))}<div class="lesson-stage"><div class="lesson-stage-main">${scene('ROLEPLAY · AT A CAFÉ · A1','A coffee, please','☕')}<article class="lesson-content-card"><span class="eyebrow">YOUR CONVERSATION</span><div class="dialogue"><div class="chat-bubble"><small>BARISTA</small><p>Hei! Mitä saisi olla?</p><span>Hi! What can I get you?</span><button class="play" data-speak="Hei! Mitä saisi olla?">▶</button></div><div class="chat-bubble me"><small>YOU</small><p>_____</p><span>Choose a reply below</span></div></div><div class="response-options">${[['Yksi kahvi, kiitos.','One coffee, please.'],['Missä on asema?','Where is the station?'],['Minä asun Suomessa.','I live in Finland.']].map(([f,m],i)=>`<button class="match-option ${quizChoice===i?(i===0?'correct':'incorrect'):''}" data-roleplay-answer="${i}"><strong>${f}</strong><small>${m}</small></button>`).join('')}</div><div class="scene-controls"><button class="button button-secondary" data-action="type-reply">Type a reply</button><button class="button button-soft" data-action="next-scene">Next line →</button></div><div class="inline-status">${quizChoice===0?'Hyvä! The barista understands.':quizChoice>0?'That phrase is useful, but it does not answer the barista here.':'Pick a reply or try your own Finnish.'}</div></article></div><aside class="lesson-side"><article class="lesson-side-card"><span class="eyebrow">USEFUL PHRASE</span><h3>Yksi ___, kiitos.</h3><p>One ___, please.</p><button class="play" data-speak="Yksi kahvi, kiitos.">▶</button></article><article class="lesson-side-card"><span class="eyebrow">CONVERSATION SKILLS</span><strong>Listen · Reply · Continue</strong><p>Short everyday exchanges from beginner to advanced.</p></article></aside></div>${section('OTHER EVERYDAY SCENES','Choose where to practise next','A small conversation for a café, shop, bus, university, workplace or new neighbour.',`<div class="home-quick-grid">${[['🚋','Buy a ticket'],['🥕','At a market'],['🎓','Ask on campus'],['💼','A job interview']].map(([i,t])=>`<button class="quick-card" data-action="change-scene"><span class="tool-icon">${i}</span><span class="quick-card-copy"><strong>${t}</strong><small>Open this roleplay →</small></span></button>`).join('')}</div>`)}`}
  function voice(){const female=['Sini · warm','Aino · clear','Ella · calm','Venla · bright','Emilia · gentle'],male=['Mikko · warm','Ari · clear','Elias · calm','Lauri · bright','Onni · gentle'];return `${pageHead('SKILL LAB · FINNISH AUDIO','Choose the voice that helps you learn.','Compare available Finnish voice options, adjust the pace and listen to a short phrase. Voice options depend on your device and the connected speech service.',`<label class="filter-chip">PACE <select><option>Natural</option><option>Slow</option><option>Steady</option></select></label>`)}<div class="goal-card"><div><span class="eyebrow">AUDIO FOR LEARNING</span><h3>Hear the same Finnish as many times as you need.</h3><p>Choose a voice for Finnish audio. English and বাংলা are for explanations; the Finnish sample stays Finnish.</p></div><button class="button button-primary" data-speak="Hei! Harjoitellaan suomea yhdessä.">▶ Preview Finnish</button></div>${section('FEMALE VOICE OPTIONS','Choose a voice to preview','Illustrative voice choices for this mockup. The final options depend on the connected Finnish speech provider.',`<div class="voice-grid">${female.map((v,i)=>`<button class="voice-card ${i===0?'active':''}" data-voice="${v}"><span class="voice-avatar rose">${v[0]}</span><strong>${v.split(' · ')[0]}</strong><small>${v.split(' · ')[1]}</small><span class="tag">FEMALE · PREVIEW</span></button>`).join('')}</div>`)}${section('MALE VOICE OPTIONS','Pick a different natural sound','The selected voice can be used across lesson phrases and word audio.',`<div class="voice-grid">${male.map(v=>`<button class="voice-card" data-voice="${v}"><span class="voice-avatar blue">${v[0]}</span><strong>${v.split(' · ')[0]}</strong><small>${v.split(' · ')[1]}</small><span class="tag">MALE · PREVIEW</span></button>`).join('')}</div>`)}<article class="lesson-content-card"><span class="eyebrow">TRY THIS FINNISH SENTENCE</span><h3>Hei! Harjoitellaan suomea yhdessä.</h3><p>Hi! Let’s practise Finnish together.</p><button class="button button-secondary" data-speak="Hei! Harjoitellaan suomea yhdessä.">▶ Play selected voice</button><small class="muted">The browser voice preview is a placeholder in this design; connected Finnish voices will be verified during implementation.</small></article>`}
  function videos(){let vids=[['♫','Finnish sounds and alphabet','Pre-A1 · 4 min','Listen for clear vowels and long sounds.'],['🔢','Numbers you can use today','Pre-A1 · 6 min','Count, ask the price and understand a number.'],['👋','Greetings in everyday Finland','A1 · 5 min','Hear a few natural ways to say hello.'],['🛒','At a Finnish supermarket','A1 · 8 min','Follow a simple shopping conversation.'],['🚋','Take a tram in Helsinki','A2 · 7 min','Learn the words for ticket, stop and direction.'],['🎓','A day at university','B1 · 9 min','Explore campus language and student life.']];return `${pageHead('SKILL LAB · WATCH AND LEARN','Finnish in pictures, scenes and short video.','Short visual lessons pair Finnish listening with everyday situations. Choose a level and follow the words as you watch.',btn('Choose level','videos-level','secondary'))}${section('WATCH A SHORT LESSON','Finnish you can see and hear','Illustrative lesson cards; final videos will use reviewed sources and captions.',`<div class="video-grid">${vids.map(([ico,title,meta,desc],i)=>`<button class="video-card" data-video="${i}"><div class="video-art" style="background-image:linear-gradient(0deg,rgba(17,54,45,.70),rgba(17,54,45,.04)),url('../public/images/kielo-cover.webp')"><span class="video-symbol">${ico}</span><span class="video-play">▶</span><span class="tag">${meta}</span></div><div class="video-copy"><span class="eyebrow">FINNISH · ${i<2?'SOUND & BASICS':'REAL LIFE'}</span><h3>${title}</h3><p>${desc}</p><span class="video-link">Open lesson preview →</span></div></button>`).join('')}</div>`)}${section('MAKE VIDEO ACCESSIBLE','Your learning, your pace','Captions, playback speed, written transcript and bilingual explanations will accompany supported videos.',`<div class="home-quick-grid"><article class="quick-card"><span class="tool-icon">CC</span><span class="quick-card-copy"><strong>Captions</strong><small>Read Finnish while you listen.</small></span></article><article class="quick-card"><span class="tool-icon">A↔</span><span class="quick-card-copy"><strong>Meaning support</strong><small>Switch lesson explanations to English or বাংলা.</small></span></article><article class="quick-card"><span class="tool-icon">◷</span><span class="quick-card-copy"><strong>Slow the pace</strong><small>Replay a phrase at your speed.</small></span></article></div>`)}`}
  function culture(){const [icon,title,desc]=topics[topicIndex];return `${pageHead('FINLAND · LANGUAGE IN ITS PLACE','Explore Finland through Finnish.','A culture and everyday-life library with 19 guided chapters. Learn the language beside the places, people and services where you might use it.',btn('Start a Finland trail','trail','primary'))}${section('FOUR WAYS TO EXPLORE','Choose a trail that fits your curiosity','Each trail connects a few chapters into a practical learning journey.',`<div class="finland-trails">${[['🧭','Get your bearings','History · state · people · seasons'],['🏡','Make a life','Moving · home · health · study · work'],['🚋','Move through daily life','Transport · market · culture · traditions'],['🌲','Explore the land','Forest · water · regions · energy']].map(([i,t,d],n)=>`<button class="trail-card ${n===0?'active':''}" data-trail="${n}"><span>${i}</span><strong>${t}</strong><small>${d}</small></button>`).join('')}</div>`)}${section('19 CHAPTERS · BEGINNER TO ADVANCED','Choose a part of Finland to explore','Every chapter pairs cultural context, useful Finnish, an audio phrase and a short levelled activity.',`<div class="topic-grid">${topics.map(([ico,t,d,tr],i)=>`<button class="topic-card ${topicIndex===i?'active':''}" data-topic="${i}"><span class="topic-icon">${ico}</span><span class="topic-card-num">${String(i+1).padStart(2,'0')}</span><strong>${t}</strong><small>${d}</small><span class="tag">${tr}</span></button>`).join('')}</div>`)}${section('CHAPTER PREVIEW · '+String(topicIndex+1).padStart(2,'0'),title,desc,`<div class="topic-detail"><div>${scene('FINLAND · CHAPTER '+String(topicIndex+1).padStart(2,'0'),title,icon)}<div class="topic-phrase"><span class="eyebrow">USEFUL FINNISH · PRE-A1</span><strong>${topicIndex===6?'Missä on rautatieasema?':topicIndex===7?'Opiskelen yliopistossa.':topicIndex===8?'Etsin työtä.':topicIndex===4?'Metsä on kaunis.':'Tervetuloa Suomeen.'}</strong><span>${topicIndex===6?'Where is the railway station?':topicIndex===7?'I study at a university.':topicIndex===8?'I am looking for work.':topicIndex===4?'The forest is beautiful.':'Welcome to Finland.'} · <span class="bn">${topicIndex===6?'রেলস্টেশন কোথায়?':'ফিনল্যান্ডে স্বাগতম।'}</span></span><button class="play" data-speak="${topicIndex===6?'Missä on rautatieasema?':topicIndex===7?'Opiskelen yliopistossa.':topicIndex===8?'Etsin työtä.':'Tervetuloa Suomeen.'}">▶ Listen</button></div></div><div class="lesson-side"><article class="lesson-side-card"><span class="eyebrow">IN THIS CHAPTER</span><h3>${title}</h3><p>${desc}. Read a short overview, notice a few useful words and try a small activity.</p><button class="button button-primary" data-action="chapter-open">Open chapter →</button></article><article class="lesson-side-card"><span class="eyebrow">WORDS TO NOTICE</span><strong>${words[(topicIndex+3)%words.length][0]}</strong><p>${translation(words[(topicIndex+3)%words.length][1],words[(topicIndex+3)%words.length][2])}</p></article></div></div><div class="inline-status">Context, facts and service links will be checked against Finnish public and cultural sources when this chapter is fully built.</div>`)}`}
  function placement(){const q=['Which word means “hello”?','Choose the Finnish word for “water”.','Complete: Minä ___ Leoni.','What does “Missä?” mean?','Choose: I live in Helsinki.','Which word means “thank you”?','Complete: yksi, kaksi, ___.','What does “Metsä” mean?','Choose a spoken or written greeting.','Which ending can mean “in”?','Read: Bussi lähtee kello kahdeksan. When does the bus leave?','Choose the best description of Finnish learning level you want to try.'];let n=lessonStep;return `${pageHead('OPTIONAL · ABOUT 3 MINUTES · NO PRESSURE','Find a comfortable starting point.','This quick check gives you a suggested place to begin. It is not an exam, and you can change your level anytime.',btn('Start at Pre-A1 instead','lesson','secondary'))}<div class="placement-progress"><span>QUESTION ${n+1} OF 12</span><div class="progress-track"><span style="width:${Math.round((n+1)/12*100)}%"></span></div><span>QUICK LEVEL CHECK</span></div><article class="placement-question"><span class="eyebrow">A LITTLE FINNISH, AT YOUR PACE</span><h2>${q[n]}</h2><div class="placement-options">${(n===0?['Hei','Kiitos','Näkemiin']:n===1?['vesi','leipä','koira']:n===2?['olen','on','ovat']:n===3?['Where?','When?','Why?']:n===4?['Asun Helsingissä.','Menen Helsingistä.','Puhun suomea.']:n===5?['kiitos','hei','anteeksi']:n===6?['kolme','kaksi','viisi']:n===7?['forest','sea','city']:n===8?['Hei!','Hyvää yötä!','Anteeksi!']:n===9?['-ssa / -ssä','-sta / -stä','-lle']:n===10?['At eight o’clock','At two o’clock','Tomorrow']:['Just starting','I know some Finnish','I use Finnish often']).map((a,i)=>`<button class="result-option ${quizChoice===i?(i===0?'selected':''):''}" data-placement-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${a}</button>`).join('')}</div><div class="lesson-step-controls"><button class="button button-secondary" data-action="placement-back" ${n===0?'disabled':''}>← Back</button><span class="muted">You can skip any question</span><button class="button button-primary" data-action="placement-next">${n===11?'See my suggestion':'Next question →'}</button></div><div class="inline-status" id="placement-result">${quizChoice<0?'Choose an answer, or move on if you prefer.':''}</div></article>`}
  function lesson(){const steps=[['NOTICE','A quiet lake morning','Tuli on lämmin.','It is warm. · আবহাওয়া উষ্ণ।','Hear the long vowel'],['LISTEN','Hear the phrase','Tuli on lämmin.','Listen for the Finnish rhythm.','Tap the speaker and listen once'],['TRY','Choose what you heard','It is warm.','Pick the meaning of the sentence.','tuli = fire · lämmin = warm'],['REMEMBER','Use it in your own words','Hyvä!','You completed one small step in Finnish.','Save this phrase for later']];let [k,title,phrase,meaning,hint]=steps[lessonStep%steps.length];return `${pageHead('PRE-A1 · LESSON 01 · STEP '+(lessonStep+1)+' OF 4',title,'A short guided lesson. Look, listen, try and remember—move on whenever you are ready.',btn('Close lesson','home','secondary'))}<div class="lesson-progress-dots">${steps.map((_,i)=>`<span class="${i<=lessonStep?'active':''}"></span>`).join('')}</div><div class="lesson-stage"><div class="lesson-stage-main">${scene('PICTURE THE SCENE · FINNISH LAKES AND FORESTS','A quiet lake morning','🌅')}<article class="lesson-content-card"><span class="eyebrow">FINNISH FIRST · TAKE YOUR TIME</span><div class="lesson-word"><strong>${phrase}</strong><button class="play" data-speak="${phrase}">▶</button></div><p>${meaning}</p><div class="lesson-tip">${hint}</div></article><div class="lesson-step-controls"><span class="muted">Step ${lessonStep+1} of 4</span><button class="button button-secondary" data-action="save-word">Save for later</button><button class="button button-primary" data-action="lesson-next">${lessonStep===3?'Finish lesson':'Next step →'}</button></div></div><aside class="lesson-side"><article class="lesson-side-card"><span class="eyebrow">WORDS IN THIS SCENE</span><strong>lämmin</strong><p>warm · উষ্ণ</p><strong>järvi</strong><p>lake · হ্রদ</p></article><article class="lesson-side-card"><span class="eyebrow">YOUR PACE</span><p>No timer. Listen as many times as you want.</p><button class="text-link" data-screen="voice">Voice settings →</button></article></aside></div>`}
  function result(){return `${pageHead('YOUR LEVEL SUGGESTION','A good place to grow from.','Based on this preview check, we suggest starting around Pre-A1. You can change levels or explore other skills at any time.',btn('View learning path','path','primary'))}${section('YOUR STARTING POINT','Pre-A1 · First Finnish','Build your foundation with sounds, everyday greetings and simple phrases.',`<div class="welcome-card"><span class="card-label">A FRIENDLY FIRST STEP</span><h2>Hei! Hello!</h2><p>Five minutes is a fine start. No previous Finnish needed.</p>${btn('Start your first lesson','lesson','primary')}</div>`)}${section('KEEP EXPLORING','You are free to choose','A level suggestion is just a guide.',levelCards())}`}
  const pages={home,path,daily,dictionary,practice,sounds,listening,spoken,speaking,reading,writing,grammar,cafe,voice,videos,culture,placement,lesson,result};
  function render(target=screen){screen=pages[target]?target:'home';$('#page-content').innerHTML=pages[screen]();$('#current-page-label').textContent=screen==='lesson'?'Guided lesson':screen==='result'?'Level suggestion':titles[screen]||'Your learning home';$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.screen===screen));$$('.mobile-dock [data-screen]').forEach(b=>b.classList.toggle('active',b.dataset.screen===screen));$('#page-content').focus({preventScroll:true});document.title=`${$('#current-page-label').textContent} · Kielo`;window.scrollTo({top:0,behavior:'smooth'});}
  function setScreen(id){if(!pages[id])return;screen=id;history.replaceState(null,'',`#${id}`);render(id);closeMenu();}
  function closeMenu(){document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');}
  let toastTimer;
  function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1800);}
  function speak(text){if(!('speechSynthesis'in window)||!text)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='fi-FI';u.rate=.9;const voices=window.speechSynthesis.getVoices();const preferred=voices.find(v=>v.lang.toLowerCase().startsWith('fi'));if(preferred)u.voice=preferred;window.speechSynthesis.speak(u);}
  function openProfile(){const d=$('#prototype-dialog');$('#dialog-kicker').textContent='YOUR KIELO · SAVED ON THIS DEVICE';$('#dialog-title').textContent='Your progress & settings';$('#dialog-body').innerHTML=`<div class="dialog-profile-grid"><article class="profile-tile"><small>YOUR LEVEL</small><strong>Pre-A1</strong><p>Start anywhere and adjust any time.</p></article><article class="profile-tile"><small>COURSE PROGRESS</small><strong>06 / 60</strong><p>Guided lessons completed in this preview.</p></article><article class="profile-tile"><small>WORDS TO REVIEW</small><strong>12 words</strong><p>Saved and difficult words live here.</p></article><article class="profile-tile"><small>DAILY GOAL</small><strong>10 words</strong><p>Small sessions count.</p></article></div><div class="form-row"><label>Learning explanations</label><select id="dialog-help-language"><option value="en" ${!bn()?'selected':''}>English</option><option value="bn" ${bn()?'selected':''}>বাংলা</option></select></div><article class="lesson-side-card"><span class="eyebrow">YOUR PRIVACY</span><p>This mockup keeps preferences in the current page. The completed app will clearly explain account, sync and data choices.</p></article>`;d.showModal();}
  function renderNav(){ $('#nav-groups').innerHTML=nav.map(g=>`<section class="nav-group"><div class="nav-group-title">${g.group}</div><div class="nav-list">${g.items.map(([id,icon,label,count])=>`<button class="nav-item" data-screen="${id}"><span class="nav-icon">${icon}</span><span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`).join('')}</div></section>`).join(''); }
  renderNav();render(screen);
  document.addEventListener('click',e=>{
    const screenBtn=e.target.closest('[data-screen]');if(screenBtn){setScreen(screenBtn.dataset.screen);return;}
    const speakBtn=e.target.closest('[data-speak]');if(speakBtn){speak(speakBtn.dataset.speak);return;}
    const set=e.target.closest('[data-set]');if(set){dailySet=+set.dataset.set;render('daily');return;}
    const filter=e.target.closest('[data-filter]');if(filter){dailyFilter=filter.dataset.filter;render('daily');return;}
    const topic=e.target.closest('[data-topic]');if(topic){topicIndex=+topic.dataset.topic;render('culture');return;}
    const trail=e.target.closest('[data-trail]');if(trail){$$('.trail-card').forEach(x=>x.classList.remove('active'));trail.classList.add('active');toast(['Get your bearings','Make a life','Move through daily life','Explore the land'][+trail.dataset.trail]+' trail selected');return;}
    const voice=e.target.closest('[data-voice]');if(voice){$$('.voice-card').forEach(x=>x.classList.remove('active'));voice.classList.add('active');speak('Hei! Harjoitellaan suomea yhdessä.');return;}
    const quiz=e.target.closest('[data-quiz]');if(quiz){quizChoice=+quiz.dataset.quiz;render(screen);return;}
    const ga=e.target.closest('[data-grammar-answer]');if(ga){quizChoice=+ga.dataset.grammarAnswer;render('grammar');return;}
    const ra=e.target.closest('[data-roleplay-answer]');if(ra){quizChoice=+ra.dataset.roleplayAnswer;render('cafe');return;}
    const pa=e.target.closest('[data-placement-answer]');if(pa){quizChoice=+pa.dataset.placementAnswer;$$('.result-option').forEach((x,i)=>x.classList.toggle('selected',i===quizChoice));return;}
    const read=e.target.closest('[data-reading-answer]');if(read){$('#reading-feedback').textContent=+read.dataset.readingAnswer===0?'Correct — aurinko means sun.':'Try again: aurinko means sun.';return;}
    const key=e.target.closest('[data-key]');if(key){const input=$('#writing-draft');const p=input.selectionStart;input.setRangeText(key.dataset.key,p,p,'end');input.focus();return;}
    const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;
    if(action==='open-lesson'){setScreen('path');toast(`${a.dataset.level||'Pre-A1'} learning path selected`);}
    else if(action==='lesson'||action==='lesson-step'){lessonStep=+(a.dataset.step||0);setScreen('lesson');}
    else if(action==='lesson-next'){lessonStep=(lessonStep+1)%4;if(lessonStep===0)setScreen('home');else render('lesson');}
    else if(action==='placement'){lessonStep=0;quizChoice=-1;setScreen('placement');}
    else if(action==='placement-back'){lessonStep=Math.max(0,lessonStep-1);quizChoice=-1;render('placement');}
    else if(action==='placement-next'){if(lessonStep===11)setScreen('result');else{lessonStep++;quizChoice=-1;render('placement');}}
    else if(action==='morphology'){setScreen('grammar');}
    else if(action==='chapter-open'){setScreen('lesson');}
    else if(action==='transcript'){const slot=$('#transcript-slot');slot.innerHTML=slot.innerHTML?'<span></span>':`<div class="transcript"><p><strong>BARISTA:</strong> Hei! Mitä saisi olla?</p><p><strong>YOU:</strong> Yksi kahvi, kiitos.</p><p><strong>BARISTA:</strong> Haluatko maitoa?</p></div>`;}
    else if(action==='answer-check'){const val=$('#practice-answer')?.value||'';toast(val.toLowerCase().includes('olen')?'Nice start — Minä olen… is a useful introduction.':'Try starting with “Minä olen…”');}
    else if(action==='mic'){toast('Speaking practice opens only when you choose it in the completed app.');}
    else if(action==='next-prompt'){toast('Next prompt: Olen kotoisin… (I am from…)');}
    else if(action==='reading-quiz'){toast('Pick the answer below the text.');}
    else if(action==='writing-hint'){$('#writing-feedback').textContent='Try: Minä olen [name]. Olen kotoisin [place]. Asun [cityssä].';}
    else if(action==='clear-draft'){$('#writing-draft').value='';}
    else if(action==='grammar-topic'){toast('Grammar topic preview selected.');}
    else if(action==='change-scene'||action==='scene-list'||action==='next-scene'){toast('Scene preview selected.');}
    else if(action==='type-reply'){toast('Type your reply in the completed conversation activity.');}
    else if(action==='trail'){setScreen('culture');}
    else if(action==='videos-level'){toast('Browse lessons from Pre-A1 to C2.');}
    else if(action==='save-word'){const word=a.dataset.word||'This phrase';toast(`${word} saved for review.`);}
    else if(action==='toast'){toast(a.dataset.message||'Saved in this preview.');}
    else if(action==='speak-sample'){speak(a.dataset.sample||'Hei!');}
  });
  $('#menu-toggle').addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
  $('#sidebar-scrim').addEventListener('click',closeMenu);$('#mobile-menu-open').addEventListener('click',()=>{document.body.classList.add('menu-open');$('#menu-toggle').setAttribute('aria-expanded','true');});
  $('#profile-button').addEventListener('click',openProfile);$('#sidebar-profile-button').addEventListener('click',openProfile);$('#dialog-close').addEventListener('click',()=>$('#prototype-dialog').close());
  $('#dialog-body').addEventListener('change',e=>{if(e.target.id==='dialog-help-language'){$('#help-language').value=e.target.value;render(screen);openProfile();}});
  $('#help-language').addEventListener('change',()=>render(screen));$('#interface-language').addEventListener('change',e=>toast(e.target.value==='FI'?'Finnish interface preview selected.':'English interface selected.'));
  $('#learning-search-form').addEventListener('submit',e=>{e.preventDefault();const q=$('#learning-search-input').value.trim().toLowerCase();if(fullVocabulary().some(w=>String(w[0]).toLowerCase()===q||String(w[1]).toLowerCase()===q||String(w[2]).toLowerCase()===q)){setScreen('dictionary');$('#dictionary-input').value=q;$('#dictionary-form').requestSubmit();}else{toast(q?`Search preview for “${q}”.`:'Type a word, lesson or skill to search.');}});
  $('#page-content').addEventListener('submit',e=>{if(e.target.id==='dictionary-form'){e.preventDefault();const q=$('#dictionary-input').value.trim().toLowerCase();const found=fullVocabulary().filter(w=>w.some(v=>String(v).toLowerCase().includes(q)));$('#dictionary-results').innerHTML=section('DICTIONARY RESULTS',q?`Matches for “${q}”`:'All learner words',found.length?`${found.length} useful ${found.length===1?'entry':'entries'} in this preview.`:'No exact match yet. Try Finnish, English or বাংলা.',found.length?wordCards(found):'<div class="empty-state">Try “leipä”, “bread” or “রুটি”.</div>');}});
  $('#search-mobile').addEventListener('click',()=>{$('#learning-search-input').focus();});
  $('#learning-search-input').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();e.currentTarget.focus();}});
  window.addEventListener('hashchange',()=>render(location.hash.slice(1)||'home'));
})();
